                </div>
                <div className={styles.catInfo}>
                  <div className={styles.catTitle}>{cat.title}</div>
                  <div className={styles.catCountBadge}>
                    {displayCount} {liveCount === 1 ? cat.unit.replace(/s$/, '') : cat.unit}
