                </div>

                <div className={styles.builderBody}>
                  <h3 className={styles.builderTitle} title={b.name}>{b.name}</h3>
                  <div className={styles.builderMetaRow}>
                    <span className={styles.builderCountBadge}>
                      {bCount} {bCount === 1 ? 'Project' : 'Projects'}
